63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    /**
114	     * Rejects an owner payload that is missing or blank in any of the required fields
115	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
116	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
117	     * value as present; this guard closes that gap so a blank in any required field is
118	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
119	     * the name of each offending field.
120	     */
121	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
122	        List<String> missing = new ArrayList<>();
123	        if (isBlank(ownerFieldsDto.getFirstName())) {
124	            missing.add("firstName");
125	        }
126	        if (isBlank(ownerFieldsDto.getLastName())) {
127	            missing.add("lastName");
128	        }
129	        if (isBlank(normalizedAddress)) {
130	            missing.add("address");
131	        }
132	        if (isBlank(ownerFieldsDto.getCity())) {
133	            missing.add("city");
134	        }
135	        if (isBlank(ownerFieldsDto.getTelephone())) {
136	            missing.add("telephone");
137	        }
138	        if (!missing.isEmpty()) {
139	            throw new MissingOwnerFieldsException(missing);
140	        }
141	    }
142	
143	    private static boolean isBlank(String value) {
144	        return value == null || value.isBlank();
145	    }
146	
147	    /**
148	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
149	     */
150	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
151	
152	    /**
153	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
154	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
155	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
156	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
157	     * stored as '+61412345678'. A value that cannot form a valid E.164 number is rejected via
158	     * {@link InvalidTelephoneException}, which the exception handler translates to a 400.
159	     */
160	    private static String normalizeTelephone(String telephone) {
161	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
162	        String e164;
163	        if (cleaned.startsWith("+")) {
164	            e164 = cleaned;
165	        } else {
166	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
167	            e164 = "+61" + national;
168	        }
169	        if (!E164_PATTERN.matcher(e164).matches()) {
170	            throw new InvalidTelephoneException(telephone);
171	        }
172	        return e164;
173	    }
174	
175	    /**
176	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
177	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
178	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
179	     */
180	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
181	
182	    /**
183	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
184	     * optional). When present it must be a syntactically valid address; a valid value is
185	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
186	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
187	     */
188	    private static String normalizeEmail(String email) {
189	        if (email == null) {
190	            return null;
191	        }
192	        if (!EMAIL_PATTERN.matcher(email).matches()) {
193	            throw new InvalidEmailException(email);
194	        }
195	        return email.toLowerCase(Locale.ROOT);
196	    }
197	
198	    /**
199	     * Rejects a create whose normalized telephone is already used by another owner. Each
200	     * existing owner's stored telephone is reduced to its E.164 form the same way {@code
201	     * normalizeTelephone} does, so the comparison is on the canonical E.164 value regardless of
202	     * the format each was originally entered in. An existing value that cannot form a valid E.164
203	     * number is skipped rather than colliding. A match is reported via
204	     * {@link DuplicateTelephoneException}, which the exception handler translates to a 409.
205	     */
206	    private void rejectDuplicateTelephone(String normalizedTelephone) {
207	        for (Owner existing : this.clinicService.findAllOwners()) {
208	            String existingE164;
209	            try {
210	                existingE164 = normalizeTelephone(existing.getTelephone());
211	            } catch (InvalidTelephoneException ex) {
212	                continue;
213	            }
214	            if (normalizedTelephone.equals(existingE164)) {
215	                throw new DuplicateTelephoneException(normalizedTelephone);
216	            }
217	        }
218	    }
219	
220	    /**
221	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
222	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
223	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
224	     * spacing do not defeat the duplicate-household check.
225	     */
226	    private static String collapse(String value) {
227	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
228	    }
229	
230	    /**
231	     * Normalizes an owner's address into a canonical form applied on every create: leading and
232	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
233	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
234	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
235	     * and returned, and is the form every address comparison (duplicate-household detection and the
236	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
237	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
238	     * so normalizing an already-normalized address is a no-op.
239	     */
240	    private static String normalizeAddress(String address) {
241	        if (address == null) {
242	            return "";
243	        }
244	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
245	        if (collapsed.isEmpty()) {
246	            return "";
247	        }
248	        String[] tokens = collapsed.split(" ");
249	        StringBuilder sb = new StringBuilder(collapsed.length());
250	        for (int i = 0; i < tokens.length; i++) {
251	            String token = tokens[i];
252	            switch (token) {
253	                case "ST" -> token = "STREET";
254	                case "RD" -> token = "ROAD";
255	                case "AVE" -> token = "AVENUE";
256	                default -> {
257	                }
258	            }
259	            if (i > 0) {
260	                sb.append(' ');
261	            }
262	            sb.append(token);
263	        }
264	        return sb.toString();
265	    }
266	
267	    /**
268	     * Rejects a create that would place a second owner in the same household as an existing one -
269	     * i.e. another owner already has the same {@code lastName} and the same {@code address},
270	     * compared case-insensitively with collapsed whitespace. The caller can opt in to sharing a
271	     * household by setting {@code sharesHousehold} true, in which case this check is skipped. A
272	     * match is reported via {@link DuplicateHouseholdException}, which the exception handler
273	     * translates to a 409.
274	     */
275	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
276	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
277	            return;
278	        }
279	        String lastName = collapse(ownerFieldsDto.getLastName());
280	        for (Owner existing : this.clinicService.findAllOwners()) {
281	            if (lastName.equals(collapse(existing.getLastName()))
282	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
283	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
284	            }
285	        }
286	    }
287	
288	    /**
289	     * Builds the {@code customerCode} for a newly created owner, formatted
290	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first three letters of
291	     * {@code city}, {@code LAST3} the upper-cased first three letters of {@code lastName}, and
292	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of
293	     * owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
294	     */
295	    private String nextCustomerCode(String city, String lastName) {
296	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
297	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
298	        int sequence = 1;
299	        for (Owner existing : this.clinicService.findAllOwners()) {
300	            if (city.equalsIgnoreCase(existing.getCity())) {
301	                sequence++;
302	            }
303	        }
304	        return String.format("%s-%s-%04d", city3, last3, sequence);
305	    }
306	
307	    /**
308	     * Builds the {@code membershipNumber} for a newly created owner, formatted
309	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
310	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
311	     */
312	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
313	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
314	    }
315	
316	    /**
317	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
318	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
319	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
320	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
321	     * receives the identical, non-blank identifier without needing to read any other owner's value.
322	     */
323	    private static String householdIdFor(String lastName, String address) {
324	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
325	        try {
326	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
327	            StringBuilder sb = new StringBuilder(32);
328	            for (int i = 0; i < 8; i++) {
329	                sb.append(String.format("%02X", digest[i]));
330	            }
331	            return sb.toString();
332	        } catch (NoSuchAlgorithmException ex) {
333	            throw new IllegalStateException("SHA-256 not available", ex);
334	        }
335	    }
336	
337	    /**
338	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
339	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
340	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
341	     */
342	    private int countNamesakes(String firstName, String lastName) {
343	        int count = 0;
344	        for (Owner existing : this.clinicService.findAllOwners()) {
345	            if (firstName.equalsIgnoreCase(existing.getFirstName())
346	                && lastName.equalsIgnoreCase(existing.getLastName())) {
347	                count++;
348	            }
349	        }
350	        return count;
351	    }
352	
353	    /**
354	     * The maximum number of owners any single city may contain. A create whose city already
355	     * holds this many owners is rejected.
356	     */
357	    private static final int CITY_CAPACITY = 50;
358	
359	    /**
360	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
361	     * compared case-insensitively - the same way the city is matched when building the
362	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
363	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
364	     * translates to a 409.
365	     */
366	    private void rejectCityAtCapacity(String city) {
367	        int count = 0;
368	        for (Owner existing : this.clinicService.findAllOwners()) {
369	            if (city.equalsIgnoreCase(existing.getCity())) {
370	                count++;
371	            }
372	        }
373	        if (count >= CITY_CAPACITY) {
374	            throw new CityAtCapacityException(city);
375	        }
376	    }
377	
378	    /**
379	     * The maximum number of owners that may be created on any single day (by
380	     * {@code registrationDate}). A create attempted once this many owners already carry the
381	     * current day's registration date is rejected.
382	     */
383	    private static final int DAILY_OWNER_LIMIT = 100;
384	
385	    /**
386	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry today's
387	     * {@code registrationDate} (the date the new owner will itself receive). The count reflects
388	     * the state prior to this create. When the limit is reached the create is reported via
389	     * {@link DailyOwnerLimitExceededException}, which the exception handler translates to a 429
390	     * Too Many Requests.
391	     */
392	    private void rejectDailyOwnerLimit() {
393	        LocalDate today = LocalDate.now();
394	        int count = 0;
395	        for (Owner existing : this.clinicService.findAllOwners()) {
396	            if (today.equals(existing.getRegistrationDate())) {
397	                count++;
398	            }
399	        }
400	        if (count >= DAILY_OWNER_LIMIT) {
401	            throw new DailyOwnerLimitExceededException();
402	        }
403	    }
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
408	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
409	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
410	        rejectDuplicateHousehold(ownerFieldsDto, normalizedAddress);
411	        rejectCityAtCapacity(ownerFieldsDto.getCity());
412	        rejectDailyOwnerLimit();
413	        HttpHeaders headers = new HttpHeaders();
414	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
415	        owner.setAddress(normalizedAddress);
416	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
417	        rejectDuplicateTelephone(normalizedTelephone);
418	        owner.setTelephone(normalizedTelephone);
419	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
420	        if (owner.getRegistrationDate() == null) {
421	            owner.setRegistrationDate(LocalDate.now());
422	        }
423	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
424	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
425	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
426	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
427	        this.clinicService.saveOwner(owner);
428	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
429	        headers.setLocation(UriComponentsBuilder.newInstance()
430	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
431	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
432	    }
433	
434	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
435	    @Override
436	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
437	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
438	        if (currentOwner == null) {
439	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
440	        }
441	        currentOwner.setAddress(ownerFieldsDto.getAddress());
442	        currentOwner.setCity(ownerFieldsDto.getCity());
443	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
444	        currentOwner.setLastName(ownerFieldsDto.getLastName());
445	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
446	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
447	        this.clinicService.saveOwner(currentOwner);
448	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
449	    }
450	
451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Transactional
453	    @Override
454	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
455	        Owner owner = this.clinicService.findOwnerById(ownerId);
456	        if (owner == null) {
457	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
458	        }
459	        this.clinicService.deleteOwner(owner);
460	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
461	    }
462	
463	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
464	    @Override
465	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
466	        Owner owner = this.clinicService.findOwnerById(ownerId);
467	        if (owner == null) {
468	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
469	        }
470	        HttpHeaders headers = new HttpHeaders();
471	        Pet pet = petMapper.toPet(petFieldsDto);
472	        owner.setId(ownerId);
473	        pet.setOwner(owner);
474	        pet.getType().setName(null);
475	        this.clinicService.savePet(pet);
476	        PetDto petDto = petMapper.toPetDto(pet);
477	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
478	            .buildAndExpand(pet.getId()).toUri());
479	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
480	    }
481	
482	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
483	    @Override
484	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
485	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
486	        if (currentOwner != null) {
487	            Pet currentPet = this.clinicService.findPetById(petId);
488	            if (currentPet != null) {
489	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
490	                currentPet.setName(petFieldsDto.getName());
491	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
492	                this.clinicService.savePet(currentPet);
493	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
494	            }
495	        }
496	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
497	    }
498	
499	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
500	    @Override
501	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
502	        HttpHeaders headers = new HttpHeaders();
503	        Visit visit = visitMapper.toVisit(visitFieldsDto);
504	        Pet pet = new Pet();
505	        pet.setId(petId);
506	        visit.setPet(pet);
507	        this.clinicService.saveVisit(visit);
508	        VisitDto visitDto = visitMapper.toVisitDto(visit);
509	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
510	            .buildAndExpand(visit.getId()).toUri());
511	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
512	    }
513	
514	
515	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
516	    @Override
517	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
518	        Owner owner = this.clinicService.findOwnerById(ownerId);
519	        if (owner != null) {
520	            Pet pet = owner.getPet(petId);
521	            if (pet != null) {
522	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
523	            }
524	        }
525	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
526	    }
527	}
